import React, { useState } from 'react';
import { Calendar, Clock, Sparkles, MapPin, UtensilsCrossed, ChefHat, Circle as Glass, CheckCircle2, ArrowRight } from 'lucide-react';

const initialForm = {
  name: '',
  email: '',
  guests: 4,
  date: '',
  time: '18:00',
};

export default function Reservations() {
  const [formData, setFormData] = useState(initialForm);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isSuccess, setIsSuccess] = useState(false);

  const validate = (values) => {
    const errors = {};
    if (!values.name.trim()) errors.name = 'Please enter your name';
    if (!values.email || !/^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,4}$/i.test(values.email)) errors.email = 'Please enter a valid email';
    if (values.guests < 1 || values.guests > 10) errors.guests = 'Guests must be between 1 and 10';
    if (!values.date || !values.time) errors.date = 'Please select a date and time';
    return errors;
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    const errors = validate(formData);
    if (Object.keys(errors).length === 0) {
      setIsSubmitting(true);
      setTimeout(() => {
        setIsSubmitting(false);
        setIsSuccess(true);
        setTimeout(() => setIsSuccess(false), 2000);
      }, 1200);
    } else {
      e.target.style.outline = '2px solid red';
    }
  };

  return (
    <section className="py-24 bg-white flex items-center justify-center min-h-[80vh]">
      <div className="max-w-xl w-full lg:max-w-2xl p-6 rounded-2xl bg-amber-900/10 border border-stone-200 shadow-2xl backdrop-blur-xl">
        <div className="mb-8 flex flex-col lg:flex-row gap-6 items-start justify-between">
          <div className="flex flex-col gap-2">
            <h2 className="text-xl sm:text-2xl font-bold text-stone-600">Save a Table</h2>
            <p className="text-stone-600 text-sm max-w-md">We're a cozy trattoria. Make a reservation to enjoy our seasonal specials.</p>
          </div>
          <div className="flex items-center gap-2">
            <div className="p-2 rounded-xl bg-amber-500/10 border border-amber-500/20 text-amber-400 text-xs font-medium">
              <Sparkles className="w-3.5 h-3.5 mr-1.5" />
              <span>Casa Verde</span>
            </div>
            <div className="p-1 rounded-xl bg-[#f3ece2] border border-stone-200 text-stone-600/50 text-xs">
              <Clock className="w-3.5 h-3.5 mr-1.5" />
              <span>Open Mon-Sun 11:00 - 23:00</span>
            </div>
          </div>
        </div>

        {isSuccess ? (
          <div className="py-8 text-center space-y-4">
            <div className="w-16 h-16 rounded-full bg-gradient-to-br from-amber-700 to-orange-800 border border-amber-600/20 flex items-center justify-center mb-4 shadow-lg shadow-amber-500/20">
              <CheckCircle2 className="w-8 h-8 text-stone-600" />
            </div>
            <h3 className="text-xl font-semibold text-stone-600">Reservation Confirmed!</h3>
            <p className="text-stone-600 text-sm max-w-md mx-auto">We'll see you for your <span className="text-amber-400">{formData.date} at {formData.time}</span>. Enjoy your meal!</p>
            <button onClick={() => setIsSuccess(false)} className="bg-amber-600/10 hover:bg-amber-400/20 text-amber-300 rounded-lg border border-amber-500/10 p-3 font-semibold transition-all duration-300 text-sm">Reserve Another Table</button>
          </div>
        ) : (
          <form onSubmit={handleSubmit} className="space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div className="relative group">
                <input 
                  type="text" 
                  placeholder="Name & Phone" 
                  className="w-full bg-amber-900/20 border border-stone-700/40 rounded-xl py-3 pl-4 pr-10 text-stone-600 focus:ring-2 focus:ring-amber-500/40 outline-none transition-all duration-300 placeholder:text-stone-500"
                  value={formData.name} 
                  onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                  required
                />
                <label className="absolute left-3 top-2.5 text-stone-600 group-hover:text-stone-600 transition-all duration-300 pointer-events-none">Full Name</label>
                {formData.name && <div className="absolute right-3 top-2.5 text-stone-600 group-hover:text-stone-600 transition-all duration-300 pointer-events-none">✓</div>}
              </div>
              <div className="relative group">
                <input 
                  type="email" 
                  placeholder="Email Address" 
                  className="w-full bg-amber-900/20 border border-stone-700/40 rounded-xl py-3 pl-4 pr-10 text-stone-600 focus:ring-2 focus:ring-amber-500/40 outline-none transition-all duration-300 placeholder:text-stone-500"
                  value={formData.email} 
                  onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                  required
                />
                <label className="absolute left-3 top-2.5 text-stone-600 group-hover:text-stone-600 transition-all duration-300 pointer-events-none">Email</label>
                {formData.email && <div className="absolute right-3 top-2.5 text-stone-600 group-hover:text-stone-600 transition-all duration-300 pointer-events-none">✓</div>}
              </div>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div className="relative group">
                <select 
                  className="w-full bg-amber-900/20 border border-stone-700/40 rounded-xl py-3 pl-4 pr-10 text-stone-600 focus:ring-2 focus:ring-amber-500/40 outline-none transition-all duration-300 placeholder:text-stone-500"
                  value={formData.guests}
                  onChange={(e) => setFormData({ ...formData, guests: parseInt(e.target.value) })}
                  required
                >
                  <option value="1">1 Guest</option>
                  <option value="2">2 Guests</option>
                  <option value="3">3 Guests</option>
                  <option value="4" selected>4 Guests</option>
                  <option value="5">5 Guests</option>
                  <option value="6">6 Guests</option>
                  <option value="7">7 Guests</option>
                  <option value="8">8 Guests</option>
                  <option value="9">9 Guests</option>
                  <option value="10">10 Guests</option>
                </select>
                <label className="absolute left-3 top-2.5 text-stone-600 group-hover:text-stone-600 transition-all duration-300 pointer-events-none">Party Size</label>
                {formData.guests && <div className="absolute right-3 top-2.5 text-stone-600 group-hover:text-stone-600 transition-all duration-300 pointer-events-none">✓</div>}
              </div>
              <div className="relative group">
                <div className="relative">
                  <div className="absolute inset-y-0 left-0 flex items-center pl-3 pointer-events-none">
                    <Calendar className="w-4 h-4 text-stone-600" />
                  </div>
                  <input 
                    type="date" 
                    className="w-full bg-amber-900/20 border border-stone-700/40 rounded-xl py-3 pl-10 pr-4 text-stone-600 focus:ring-2 focus:ring-amber-500/40 outline-none transition-all duration-300 placeholder:text-stone-500"
                    value={formData.date}
                    onChange={(e) => setFormData({ ...formData, date: e.target.value })}
                    required
                  />
                </div>
                <label className="absolute -top-3 left-3 text-stone-600 group-hover:text-stone-600 transition-all duration-300 pointer-events-none">Date</label>
                {formData.date && <div className="absolute -top-3 right-3 text-stone-600 group-hover:text-stone-600 transition-all duration-300 pointer-events-none">✓</div>}
              </div>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div className="relative group">
                <div className="relative">
                  <div className="absolute inset-y-0 left-0 flex items-center pl-3 pointer-events-none">
                    <Clock className="w-4 h-4 text-stone-600" />
                  </div>
                  <input 
                    type="time" 
                    className="w-full bg-amber-900/20 border border-stone-700/40 rounded-xl py-3 pl-10 pr-4 text-stone-600 focus:ring-2 focus:ring-amber-500/40 outline-none transition-all duration-300 placeholder:text-stone-500"
                    value={formData.time}
                    onChange={(e) => setFormData({ ...formData, time: e.target.value })}
                    required
                  />
                </div>
                <label className="absolute -top-3 left-3 text-stone-600 group-hover:text-stone-600 transition-all duration-300 pointer-events-none">Time</label>
                {formData.time && <div className="absolute -top-3 right-3 text-stone-600 group-hover:text-stone-600 transition-all duration-300 pointer-events-none">✓</div>}
              </div>
              <div className="relative group">
                <select 
                  className="w-full bg-amber-900/20 border border-stone-700/40 rounded-xl py-3 pl-4 pr-10 text-stone-600 focus:ring-2 focus:ring-amber-500/40 outline-none transition-all duration-300 placeholder:text-stone-500"
                  value={formData.tableType}
                  onChange={(e) => setFormData({ ...formData, tableType: e.target.value })}
                  required
                >
                  <option value="">Table Type</option>
                  <option value="indoor">Indoor Seating</option>
                  <option value="outdoor">Outdoor Seating</option>
                </select>
                <label className="absolute left-3 top-2.5 text-stone-600 group-hover:text-stone-600 transition-all duration-300 pointer-events-none">Table Preference</label>
                {formData.tableType && <div className="absolute right-3 top-2.5 text-stone-600 group-hover:text-stone-600 transition-all duration-300 pointer-events-none">✓</div>}
              </div>
            </div>
            <div className="flex justify-end mt-6">
              <button 
                type="submit" 
                disabled={isSubmitting}
                className="inline-flex items-center gap-2 py-3 px-6 rounded-2xl bg-amber-600/10 text-amber-300 border border-amber-500/10 hover:bg-amber-400/10 transition-all duration-300 font-semibold text-sm"
              >
                {isSubmitting ? <div className="animate-spin text-stone-600"><span className="sr-only">Loading...</span></div> : <MapPin className="w-4 h-4" />} &nbsp;Save Table
              </button>
            </div>
          </form>
        )}
      </div>
    </section>
  );
}

.font-display { font-family: 'Playfair Display', Georgia, serif; }
